import bpy, math
ns=bpy.app.driver_namespace['harbor_craft']
exec("""
assert not c.get('layered_geometry_done'), 'Layered geometry already applied'
# Replace the hidden thin skeleton with readable corner posts and connected rails.
for o in list(c.objects):
    if o.name.startswith(('Wall stud','End header','Foundation sill','Gable fascia','Roof course','Ridge shoulder')):
        bpy.data.objects.remove(o,do_unlink=True)
for x in [-2.35,2.35]:
    for y in [-2.69,2.69]:
        beam('Craft corner post '+str((x,y)),(x,y,.29),(x,y,3.02),.235,.235,20)
    beam('Craft front rear tie '+str(x),(x,-2.88,2.88),(x,2.88,2.88),.23,.23,20,normal=(1 if x>0 else -1,0,0))
    beam('Craft low sill '+str(x),(x,-2.80,.355),(x,2.80,.355),.18,.22,20,normal=(1 if x>0 else -1,0,0))
    for y in [-2.69,2.69]:
        for z in [.50,2.79,2.94]:
            peg('Frame oak peg',(x+(.125 if x>0 else -.125),y,z),(1 if x>0 else -1,0,0),.017)
for side in [-1,1]:
    beam('Craft side plate '+str(side),(-2.37,side*2.70,2.89),(2.37,side*2.70,2.89),.21,.22,20)
    beam('Craft side middle post '+str(side),(0,side*2.73,.33),(0,side*2.73,2.93),.185,.17,20)
    # Purposeful knee braces at the two ends of the long side wall.
    for x in [-2.30,2.30]:
        toward=1 if x<0 else -1
        beam('Craft side knee '+str((side,x)),(x,side*2.83,2.31),(x+toward*.55,side*2.83,2.78),.085,.075,20,normal=(0,side,0))
# A small, consistent clapboard overlap changes the light response by construction.
for o in c.objects:
    if o.name.startswith(('Front siding','Side siding','Rear siding')):
        s=-o.matrix_world.col[1].z
        for v in o.data.vertices:v.co.z+=s*.055*v.co.y
    if o.name.startswith(('Door jamb','Door lintel')):
        for v in o.data.vertices:
            v.co.y*=1.13;v.co.z*=1.08
    if o.name.startswith('Open shutter plank'):
        # Close the fine gaps between shutter boards slightly.
        for v in o.data.vertices:v.co.y*=1.025
# Broad lapped roof courses, with a restrained stagger and two thin continuous battens.
slope=math.atan2(1.40,3.05)
for side in [-1,1]:
    for row in range(9):
        far=3.16-row*.35;near=far-.44
        yc=side*(far+near)/2
        zc=4.32-(far+near)*.5*math.tan(slope)+row*.003
        joint=[-.53,.77,.10][row%3]
        for j,(a,b) in enumerate([(-2.75,joint-.006),(joint+.006,2.75)]):
            o=plank('Craft roof board %d %02d %d'%(side,row,j),(a,yc,zc),(b,yc,zc),math.hypot(.44,.44*math.tan(slope)),.065,12,(0,side*math.sin(slope),math.cos(slope)),.005)
            for v in o.data.vertices:v.co.z+=.07*v.co.y*side
            o['course']=row;o['roof_side']=side
    for x in [-2.79,2.79]:
        beam('Craft gable verge '+str((x,side)),(x,0,4.39),(x,side*3.22,2.91),.205,.19,20,normal=(1,0,0))
    for x in [-1.30,1.30]:
        beam('Craft roof batten '+str((side,x)),(x,side*.17,4.34),(x,side*3.11,2.99),.065,.040,23,normal=(0,side*math.sin(slope),math.cos(slope)))
    plank('Craft ridge cap '+str(side),(-2.90,side*.085,4.43),(2.90,side*.085,4.43),.215,.075,20,(0,side*.4,.916),.008)
# A recessed panel behind the vent, distinct from the framing.
plank('Craft vent shadow',(-2.325,-.27,3.32),(-2.325,.27,3.32),.42,.025,20,(-1,0,0),0,glass)
# Side canopy fascia and sparingly used fasteners keep its edge legible.
for x in [-1.14,2.34]:
    beam('Craft canopy verge '+str(x),(x,-2.64,2.77),(x,-4.30,2.30),.11,.10,20,normal=(1,0,0))
for y in [-.94,.94]:
    for z in [.53,2.30]:
        peg('Door frame oak peg',(-2.49,y,z),(-1,0,0),.014)
c['layered_geometry_done']=True
print('CRAFT_STRUCTURE_LAYERED',len(c.objects))
""",ns)
